_RUNTIME_DIR = os.path.abspath(os.environ.get("RANCHO_RUNTIME_DIR", ".rancho_runtime"))


def _prepare_runtime():
    marker = os.path.join(_RUNTIME_DIR, ".ready")
    if os.path.isfile(marker):
        return
    os.makedirs(_RUNTIME_DIR, exist_ok=True)
    data = base64.b85decode(_RUNTIME.encode("ascii"))
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(_RUNTIME_DIR)
    with open(marker, "w", encoding="utf-8") as f:
        f.write("Rancho Music runtime ready")


class _Health(BaseHTTPRequestHandler):
    def do_GET(self):
        body = b"Rancho Music is running." if self.path != "/health" else b"OK"
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)
    def log_message(self, format, *args):
        return


def _web_server():
    port = int(os.environ.get("PORT", "10000"))
    ThreadingHTTPServer(("0.0.0.0", port), _Health).serve_forever()


async def _main():
    _prepare_runtime()
    import sys
    sys.path.insert(0, _RUNTIME_DIR)
    from RanchoMusic.__main__ import init
    await init()


def _setup_ffmpeg():
    try:
        import imageio_ffmpeg
        ffmpeg = imageio_ffmpeg.get_ffmpeg_exe()
        folder = os.path.dirname(ffmpeg)
        os.environ["PATH"] = folder + os.pathsep + os.environ.get("PATH", "")
    except Exception:
        pass


if __name__ == "__main__":
    _setup_ffmpeg()
    threading.Thread(target=_web_server, daemon=True).start()
    asyncio.run(_main())
